// CH 102 content, built from the NC State CH 102 Lab eManual (WebAssign).
// "exp" = typical expected results (not printed in the manual) — labelled as such in the UI.
const LABS = [
{n:0, t:"Lab skills & safety", s:"Glassware, sig figs, balance, burner, safety rules",
 big:[
  "<b>Graduated cylinder</b> = approximate (\"measure ~5 mL\"), 0.5–1% error, report 3 sig figs. <b>Buret / volumetric pipet</b> = precise (\"measure 5.00 mL\"), read to <b>0.01 mL</b>.",
  "Read the <b>bottom of the meniscus</b> at eye level (avoids parallax). A white card behind helps.",
  "<b>Conditioning</b>: rinse glassware you can't dry (buret, pipet) with small portions of the solution you'll measure, so leftover water doesn't dilute it. Buret: rinse twice with ~5 mL.",
  "<b>TD</b> (to deliver) vs <b>TC</b> (to contain). A volumetric pipet is TD: let it drain, touch off the last drop, <b>never blow it out</b>.",
  "<b>Analytical balance</b> reads to 0.001 g. Close the doors, never put chemicals directly on the pan, let hot objects cool, use the same balance for a series, record the <b>actual</b> mass.",
  "<b>Accuracy</b> = close to the true value. <b>Precision</b> = repeat measurements agree. Systematic (determinate) error hurts accuracy; random error mostly hurts precision.",
  "<b>Bunsen burner</b>: hottest spot is the <b>tip of the inner blue cone</b>. More air = hotter, bluer flame. Blow-out → shut the gas at the bench valve first. Never leave it unattended.",
  "<b>Centrifuge</b>: balance with a tube of equal volume directly opposite; never stop the rotor by hand; don't open until it stops (~30 s spin is usually enough).",
  "<b>Never</b> put a pipet or dropper into a stock bottle; pour some into a clean container. Never return excess reagent."],
 eq:["Multiply/divide → fewest <b>sig figs</b> (1.001 × 2.2 = 2.2)","Add/subtract → fewest <b>decimal places</b> (2.023 + 4.71 = 6.73)","K = °C + 273.15 · 1 mL = 1 cm³ · 1 L = 1000 mL","% error = |exp − true| / true × 100"],
 sig:[["2.34","3"],["30.067","5 (sandwiched zeros count)"],["0.00089","2 (leading zeros never count)"],["9.100","4 (trailing zeros after a decimal count)"],["300","ambiguous → write 3 × 10² or 3.00 × 10²"],["12 (a dozen)","exact, unlimited"]],
 safety:["Eye or skin splash: flush <b>at least 15 minutes</b>; big corrosive spill on body → safety shower.","Safety glasses on at all times (over prescription glasses). Contacts discouraged.","Dress code: shirt covers shoulders/midriff, pants to the ankle (no leggings/capris), closed toe and heel shoes, hair tied back, no earbuds. Fix it within <b>10 min</b> or lose <b>15 InLab points</b>.","Clothing on fire: <b>stop, drop, roll</b> (don't run). Fire alarm: burners, water, hot plates off, stairs, meet in front of Fox.","Broken glass → glass box, never trash. Report every injury, fire, spill to the TA.","Never pour heavy-metal ions or organic solvents down the drain. Dilute, non-toxic acids/bases can go down with lots of water.","No food or drink. Gloves only for select labs; never wear gloves on keyboards or in hallways.","NFPA diamond: 0 (lowest) to 4 (greatest hazard)."],
 policy:["Attend <b>9 of 11</b> labs to pass. Over 10 min late = unexcused = 0/50 InLab.","Each lab = PreLab 25 + InLab 50 + PostLab 25. First two PreLab questions (safety, waste) must be right to enter lab.","Lowest PostLab is dropped. Final exam is 100 points."]},

{n:1, t:"Moles, Mass & Volume", s:"Avogadro's number, molar mass, density, factor-label",
 purpose:"How long to count a mole of popcorn; molar masses of popcorn and marbles; volume of one water molecule vs. one marble.",
 big:["1 mole = <b>6.02 × 10²³</b> of anything (Avogadro's number).","<b>Molar mass</b> (g/mol) = mass of one item × 6.02 × 10²³. H₂O = 2(1.0) + 16.0 = <b>18.0 g/mol</b>.","<b>Density</b> = mass / volume. Water = <b>1.00 g/mL</b> at 25 °C (memorize: 1 g of water = 1 mL).","<b>Volume by displacement</b>: drop marbles in water; volume of marbles = final − initial reading.","<b>Factor-label</b>: line up conversion factors so unwanted units cancel.","Mass by difference: (container + sample) − empty container."],
 eq:["kernels/s = average count ÷ 30 s","time = 6.02 × 10²³ ÷ (kernels/s) → ÷ 3.156 × 10⁷ s/yr","mass of 1 item = mass of 12 ÷ 12","molar mass = mass of 1 item × 6.02 × 10²³","density = m / V","molar volume of water = 18.0 g/mol ÷ 1.00 g/mL = 18.0 mL/mol","volume of one H₂O = 18.0 mL ÷ 6.02 × 10²³ = 2.99 × 10⁻²³ mL"],
 worked:[["5.00 g of water is how many moles?","5.00 g × (1 mol / 18.0 g) = <b>0.278 mol</b>"],["You count 28 kernels in 30 s. Years to count a mole?","28/30 = 0.933 kernels/s → 6.02×10²³ / 0.933 = 6.45×10²³ s → ÷ 3.156×10⁷ = <b>2.0 × 10¹⁶ years</b>"],["12 marbles raise the water from 50.0 to 62.4 mL. Volume of one marble?","12.4 mL ÷ 12 = <b>1.03 mL</b>"]],
 proc:["Part A: count kernels into a beaker for 30 s, 4 trials, switch roles, average.","Part B: weigh empty beaker, add 12 kernels, weigh, subtract, ÷ 12. Repeat with marbles.","Part C: weigh empty 50 mL cylinder, fill to ~18 mL with DI water (read to 0.1 mL), weigh → density. 100 mL cylinder to 50 mL, tilt and roll in 12 marbles, read final volume."],
 traps:["Record the exact volume you got (e.g. 17.8 mL), not the 18 mL target.","Tilt the cylinder so marbles roll in: a splash loses water and makes the displaced volume too small."],
 safety:["No hazards; standard eye protection. Return popcorn and marbles (don't throw out)."]},

{n:2, t:"Emission & Absorption", s:"Flame tests, color, spectrophotometer",
 purpose:"Identify unknown ions by flame color; relate a solution's color to its absorption spectrum.",
 big:["<b>Absorption</b>: electron jumps ground → excited state. <b>Emission</b>: falls back and releases light (or heat).","<b>Flame test</b> color = the <b>emitted</b> light itself. No complementary colors.","A colored <b>solution</b> looks like the <b>complement</b> of the color it absorbs (opposite on the color wheel). Absorbs red → looks green.","Shorter λ → higher frequency → <b>higher energy</b>. Visible ≈ 400 (violet) to 700 nm (red).","<b>Transmittance</b> T = I/I₀ (fraction that gets through). <b>Absorbance</b> A = −log T (unitless). Absorption spectrum = A vs. λ.","Water <b>blank</b> sets I₀ (calibration) before reading samples.","Emission spectra are characteristic of the element → identification test. A prism/grating that separates λ is a <b>monochromator</b>."],
 eq:["c = λν = 3.0 × 10⁸ m/s","E = hν = hc/λ, h = 6.626 × 10⁻³⁴ J·s","A = −log T = −log(I/I₀)","T = 10⁻ᴬ","1 nm = 10⁻⁹ m"],
 worked:[["T = 0.25. Absorbance?","A = −log(0.25) = <b>0.602</b>"],["Energy of a 470 nm photon?","E = (6.626×10⁻³⁴)(3.0×10⁸)/(470×10⁻⁹) = <b>4.23 × 10⁻¹⁹ J</b>"],["Frequency of 635 nm light?","ν = 3.0×10⁸ / 635×10⁻⁹ = <b>4.72 × 10¹⁴ Hz</b>"]],
 tables:[{h:["Ion","Typical flame color"],r:[["Li⁺","crimson / deep red"],["Na⁺","bright yellow-orange (lingers; contaminates others)"],["K⁺","violet / lilac (faint)"],["Ca²⁺","orange-red"],["Sr²⁺","bright red"],["Ba²⁺","yellow-green"],["Cu²⁺","green / blue-green"]],cap:"Typical textbook flame colors (your lab's knowns may be a subset). Your own Data Table A is the answer key for your unknowns."},
         {h:["Dye","Looks","Absorbs (approx.)"],r:[["Tartrazine (Yellow 5)","yellow","~430 nm (violet-blue)"],["Sunset Yellow (Yellow 6)","orange","~480 nm (blue)"],["Allura Red (Red 40)","red","~500 nm (blue-green)"],["Indigo Carmine (Blue 2)","blue","~610 nm (orange)"],["Methyl Violet","violet","~590 nm (yellow)"],["Green food coloring","green","two peaks: ~430 and ~630 nm (a yellow + a blue dye)"]],cap:"Approximate literature λmax values; record your own maxima from the scan."}],
 proc:["Clean the nichrome loop: dip in 3 M HCl, heat in the hottest part of the flame until no color. Repeat.","Dip loop in a well (5 drops of 0.1 M salt), bring into flame, record color. Knowns first, then unknowns.","Spectrophotometer: read water blank (don't lift the cover ~30 s), then scan each sealed dye vial, switch to Absorbance (−log T), record λmax between 395–700 nm."],
 traps:["Flame test = emitted color (no complement). Solution color = complement of absorbed.","A higher absorbance peak at λ means that color is being removed, not seen."],
 safety:["3 M HCl is corrosive; gloves available. Never leave the burner unattended.","Waste: flame-test solutions and HCl down the sink with water. Dye vials are sealed: never open, return them."]},

{n:3, t:"Solubility Rules", s:"Precipitation, formulas, net ionic equations",
 purpose:"Build your own solubility rules by mixing 6 anions × 10 cations in a well plate.",
 big:["Every cation was supplied as a <b>nitrate</b> because all nitrates are soluble — so any precipitate comes from the other ion pair.","<b>Precipitate</b> = insoluble solid that falls out. <b>Spectator ions</b> appear unchanged on both sides and drop out of the net ionic equation.","<b>Coulomb's law</b> F = k q₁q₂ / (ε r²): bigger charges and smaller distance → stronger attraction. Water's large dielectric constant ε weakens it. Precipitates form when charges are <b>large and opposite</b>.","Charge rule: compounds with a +1 or −1 ion tend to be soluble; 2+/2− and 3+/3− pairs tend to precipitate.","<b>Group 1 and NH₄⁺ rule beats the phosphate/carbonate rule</b> (Na₃PO₄, Na₂CO₃ are soluble).","Write formulas so total + charge = total − charge: Al³⁺ + PO₄³⁻ → AlPO₄; Fe³⁺ + OH⁻ → Fe(OH)₃; Ag⁺ + PO₄³⁻ → Ag₃PO₄."],
 eq:["Molecular: Pb(NO₃)₂ + 2KI → PbI₂(s) + 2KNO₃","Total ionic: Pb²⁺ + 2NO₃⁻ + 2K⁺ + 2I⁻ → PbI₂(s) + 2K⁺ + 2NO₃⁻","Net ionic: Pb²⁺(aq) + 2I⁻(aq) → PbI₂(s)","Mg²⁺ + 2OH⁻ → Mg(OH)₂(s)","Mg²⁺ + CO₃²⁻ → MgCO₃(s)","3Mg²⁺ + 2PO₄³⁻ → Mg₃(PO₄)₂(s)"],
 tables:[{h:["Anion","General rule","Exceptions you'd see"],r:[["NO₃⁻, ClO₄⁻","always soluble","none"],["Cl⁻","soluble","Ag⁺ (AgCl), Pb²⁺ (PbCl₂)"],["SO₄²⁻","soluble","Sr²⁺, Ca²⁺, Pb²⁺ (Ag⁺ slightly; Ba²⁺ too, though not on this plate)"],["OH⁻","insoluble","Group 1, NH₄⁺, Sr²⁺, Ba²⁺ soluble; Ca(OH)₂ slightly"],["CO₃²⁻","insoluble","Group 1 and NH₄⁺ soluble"],["PO₄³⁻","insoluble","Group 1 and NH₄⁺ soluble"],["I⁻ (Part B)","soluble","Ag⁺ (AgI) and Pb²⁺ (PbI₂, yellow) precipitate"]],cap:"Standard rules that match what this well plate shows (compare with your own Y/N table)."}],
 proc:["8 × 12 well plate: cations in columns, anions in rows, 3 drops each (0.20 M). Y = precipitate, N = none. Unclear → redo in a test tube.","Part B: KI with Pb(NO₃)₂ and AgNO₃."],
 traps:["AgCl and AgI break the ±1 rule: both ions are ±1 yet they precipitate.","Hydroxide is −1 but its 2+/3+ cation salts still precipitate (Mg(OH)₂, Al(OH)₃, Fe(OH)₃).","Don't touch the well with the dropper: it contaminates the reagent bottle."],
 safety:["Pb(NO₃)₂ and AgNO₃ are toxic if swallowed. AgNO₃ leaves dark skin spots after ~24 h (harmless, fade in days).","Waste: everything into the labeled waste container (heavy metals), rinse with minimal DI water."]},

{n:4, t:"Qualitative Analysis", s:"Separating Ag⁺, Fe³⁺, Ba²⁺",
 purpose:"Design a separation scheme and confirmatory tests for Ag⁺, Fe³⁺, Ba²⁺, then identify ions in an unknown.",
 big:["Qual analysis answers \"is it there?\" (present/absent), not \"how much?\". Two phases: <b>separate</b>, then <b>confirm</b>.","Order: <b>HCl</b> removes Ag⁺ (AgCl, white) → <b>NH₃</b> makes it basic and removes Fe³⁺ (Fe(OH)₃, red-brown, gelatinous) → <b>H₂SO₄</b> removes Ba²⁺ (BaSO₄, white).","Some NH₃ reacts with the leftover HCl to make NH₄⁺; NH₄⁺ + NH₃ = a <b>buffer</b>.","Confirm Ag⁺: AgCl dissolves in NH₃ (forms Ag(NH₃)₂⁺); add 6 M HNO₃ → white AgCl comes back.","Confirm Fe³⁺: dissolve Fe(OH)₃ in HCl, add NaSCN → <b>blood-red</b> FeSCN²⁺.","<b>Supernatant</b> = liquid above the solid. <b>Decant</b> = pour it off. <b>Wash</b> the solid with water to remove trapped ions (prevents <b>false positives</b>).","<b>Test for completeness</b>: after centrifuging, add 1 more drop of reagent down the wall; no new cloudiness = all of that ion removed."],
 eq:["Ag⁺ + Cl⁻ → AgCl(s)","Fe³⁺ + 3OH⁻ → Fe(OH)₃(s)","Ba²⁺ + SO₄²⁻ → BaSO₄(s)","AgCl(s) + 2NH₃ → Ag(NH₃)₂⁺ + Cl⁻ (then HNO₃ re-forms AgCl)","Fe³⁺ + SCN⁻ → FeSCN²⁺ (blood red)"],
 tables:[{h:["Ion","Separated by","Precipitate","Confirm"],r:[["Ag⁺","6 M HCl","AgCl (ppt #1), white","NH₃ dissolves it; 6 M HNO₃ re-precipitates white AgCl"],["Fe³⁺","7.5 M NH₃","Fe(OH)₃ (ppt #2), rust-brown","dissolve in 6 M HCl, add 0.05 M NaSCN → blood red"],["Ba²⁺","6 M H₂SO₄","BaSO₄, white","the white sulfate precipitate itself"]],cap:"Colors are typical observations; the manual has you record your own."}],
 proc:["Part A: 3 × 3 grid of single ions tested with HCl, NaSCN, H₂SO₄ (keep for comparison).","Part B: mix all three → HCl until no more solid → centrifuge → test completeness → decant. NH₃ (~10 drops) on supernatant → ppt #2. H₂SO₄ (~2 drops) → BaSO₄.","Wash ppt #1 with cold water, then NH₃ + water, decant into clean tube, add HNO₃. Dissolve ppt #2 in HCl, add 1 drop NaSCN.","Part C: 9 drops of unknown, repeat the scheme, fill in the flow chart."],
 traps:["No precipitate at a step = that ion is <b>absent</b> (a valid result for an unknown).","Skipping the wash can carry Fe³⁺ into the next test and fake a red SCN⁻ result."],
 safety:["HCl, H₂SO₄, HNO₃, NH₃ are corrosive; use the hood. Balance the centrifuge.","Waste: <b>nothing down the sink</b>; all solutions and solids go in the waste container (heavy metals)."]},

{n:5, t:"Molecular Geometry", s:"Lewis structures, VSEPR, bond order, resonance",
 purpose:"Compare Lewis structures to 3D models; bond order vs. length; resonance. (Online/at-home lab with jmol.)",
 big:["<b>ER</b> = 8 × (non-H atoms) + 2 × (H atoms). <b>VE</b> = valence electrons (+1 per − charge, −1 per + charge). <b>SP</b> = ½(ER − VE). <b>LP</b> = ½(VE − 2·SP).","First atom in the formula is usually central. H makes 1 bond. Atoms with 1, 2, 3, 4 bonds need 3, 2, 1, 0 lone pairs.","<b>Formal charge</b> FC = VE(atom) − bonds − 2·LP. Sums to 0 (molecule) or the ion's charge. Best structure: smallest formal charges, negative FC on the more electronegative atom.","<b>VSEPR</b>: electron groups spread as far apart as possible. A double or triple bond counts as <b>one</b> group.","<b>Electron geometry</b> counts lone pairs; <b>molecular geometry</b> only describes atoms.","Higher <b>bond order</b> → shorter and stronger: C–C 0.154 nm > C=C 0.134 nm > C≡C 0.120 nm.","<b>Resonance</b>: same atoms and electrons, shared pairs placed differently. Equal resonance structures → all those bonds come out the same length."],
 eq:["ER = 8(non-H) + 2(H)","VE = Σ valence e⁻ ± charge","SP = ½(ER − VE)","LP = ½(VE − 2SP)","FC = VE − bonds − 2(LP)"],
 worked:[["Formate ion, CHO₂⁻","ER = 2 + 24 = 26; VE = 4 + 1 + 12 + 1 = 18; SP = ½(26 − 18) = <b>4</b>; LP = ½(18 − 8) = <b>5</b>; FCs 0, 0, 0, −1 (on the single-bonded O); two equal resonance forms."],["CO₃²⁻","ER 32, VE 24, SP 4, LP 8. One C=O + two C–O⁻, three equal resonance forms → all C–O bonds equal (bond order 4/3)."],["N₂O (N central)","VE 16, ER 24, SP 4. N≡N–O (FC 0, +1, −1) and N=N=O (−1, +1, 0). Linear, 2 groups."]],
 tables:[{h:["Groups","LP","Shape","Angle","Hybrid","Lab example"],r:[["2","0","linear","180°","sp","N₂O, C₂H₂"],["3","0","trigonal planar","120°","sp²","CH₂O, C₂H₄, CO₃²⁻"],["3","1","bent","<120° (~119°)","sp²","SO₂"],["4","0","tetrahedral","109.5°","sp³","CH₄, C₂H₆"],["4","1","trigonal pyramidal","~107°","sp³","NH₃"],["4","2","bent","~104.5°","sp³","H₂O"]],cap:"Lone pairs squeeze bond angles below the ideal value."},
         {h:["Species","Resonance","What the model shows"],r:[["Benzene C₆H₆","2 equal","all six C–C bonds equal, ~0.139 nm (between single and double)"],["CO₃²⁻","3 equal","all three C–O equal"],["SCN⁻ (C central)","unequal","formal charge favors [S=C=N]⁻ (−1 on N); measured C–N is close to a triple bond, so S–C≡N⁻ also contributes"]],cap:"Equal resonance structures are confirmed by equal measured bond lengths."}],
 proc:["Build each with the model kit (peg count = electron groups), view in jmol, measure lengths (double-click two atoms) and angles (double-click, single-click vertex, double-click)."],
 traps:["NH₃ and H₂O have <b>tetrahedral electron geometry</b> but pyramidal / bent molecular shapes.","Measured values differ a bit from VSEPR predictions; explain with lone-pair repulsion."],
 safety:["No chemicals, no waste."]},

{n:6, t:"Solid State Modeling", s:"Unit cells, coordination number, stoichiometry",
 purpose:"Build simple cubic, BCC, FCC, NaCl, CsCl, CaF₂ unit cells; count atoms, packing, coordination numbers.",
 big:["<b>Unit cell</b> = smallest repeating unit of a crystal lattice. Crystalline = long-range order; amorphous = none.","Sharing: <b>corner 1/8</b>, <b>edge 1/4</b>, <b>face 1/2</b>, <b>body center 1</b>.","Simple cubic: 8 × 1/8 = <b>1</b>. BCC: 1 + 1 = <b>2</b>. FCC: 1 + 6 × 1/2 = <b>4</b>.","<b>Coordination number</b> (touching neighbors): SC 6, BCC 8, FCC 12. Higher CN → higher packing efficiency.","Packing efficiency: <b>FCC 74% > BCC 68% > SC 52%</b>. More void volume = less efficient.","Lab's <b>atom density</b> = spheres in the cell ÷ edge³ (cm³).","Unit-cell ratio must equal the formula: NaCl 4:4, CsCl 1:1, CaF₂ 4:8 = 1:2. The bigger spheres are the anions (Cl⁻ > Na⁺; F⁻ > Ca²⁺)."],
 eq:["atoms = 8(1/8) + 6(1/2) + 12(1/4) + 1(body)","V = a³","atom density = atoms ÷ a³","(CH 101: SC a = 2r, BCC a = 4r/√3, FCC a = 2√2·r)"],
 tables:[{h:["Cell","Atoms/cell","CN","Packing"],r:[["Simple cubic","1","6","52%"],["Body-centered cubic","2","8","68%"],["Face-centered cubic","4","12","74%"]],cap:""},
         {h:["Structure","Arrangement","Count","CN"],r:[["NaCl","Cl⁻ FCC, Na⁺ in holes (also FCC, shifted)","4 Na⁺ : 4 Cl⁻","6 and 6"],["CsCl","each ion simple cubic, one at the other's cube center","1 Cs⁺ : 1 Cl⁻","8 and 8"],["CaF₂ (fluorite)","Ca²⁺ FCC, F⁻ simple cube inside","4 Ca²⁺ : 8 F⁻","Ca²⁺ 8, F⁻ 4"]],cap:"CsCl is <b>not</b> BCC: the center ion is a different ion from the corners. Either ion can be put at the corners and both cells are valid, same volume."}],
 worked:[["FCC model edge = 4.2 cm. Atom density?","V = 4.2³ = 74.1 cm³ → 4 / 74.1 = <b>0.054 spheres/cm³</b>"]],
 proc:["Build each structure on templates A–F layer by layer; count spheres inside the cell; measure an edge with a ruler (nucleus to nucleus); count touching spheres for CN."],
 traps:["Count only the fraction of each sphere inside the cube (corners are 1/8 each).","Edge is measured between sphere centers."],
 safety:["No chemicals, no waste."]},

{n:7, t:"Enthalpy & Gas Laws", s:"Exo/endothermic, ΔG = ΔH − TΔS, heating curve, Boyle's law",
 purpose:"Observe enthalpy changes in dissolving, a reaction, and phase changes; find the P–V relationship of a gas.",
 big:["<b>System</b> = dissolving/reacting chemicals; <b>surroundings</b> = the water. Thermistor measures the water.","Water warms (ΔT > 0) → system released heat → <b>exothermic</b>, ΔH < 0 (CaCl₂ dissolving).","Water cools (ΔT < 0) → system absorbed heat → <b>endothermic</b>, ΔH > 0 (NH₄NO₃ → cold pack).","Δ = final − initial. Example: 22.5 → 17.3 °C, ΔT = −5.2 °C → endothermic.","<b>ΔG = ΔH − TΔS</b>; spontaneous if ΔG < 0. A spontaneous endothermic process needs ΔS > 0.","Entropy: gas ≫ liquid > solid. Dissolving a solid and boiling increase entropy (boiling greatly).","Heating curve: temperature stays <b>flat</b> during melting (0 °C) and boiling (~100 °C): heat goes into the phase change, not raising T.","<b>Boyle's law</b>: at constant n and T, P and V are <b>inversely</b> proportional (PV = constant). Volume = independent (x-axis), pressure = dependent (y-axis)."],
 eq:["ΔT = T_final − T_initial","ΔG = ΔH − TΔS","PV = nRT, R = 0.0821 L·atm/(mol·K)","P₁V₁ = P₂V₂","Specific heat of water = 4.18 J/(g·°C); q = m·s·ΔT"],
 tables:[{h:["ΔH","ΔS","Spontaneous?"],r:[["− (exo)","+","always"],["+ (endo)","−","never"],["− (exo)","−","at low T"],["+ (endo)","+","at high T"]],cap:""},
         {h:["Process","ΔT","Type","Expected"],r:[["CaCl₂(s) dissolves","rises","exothermic","warm"],["NH₄NO₃(s) dissolves","drops","endothermic","cold pack; spontaneous because ΔS > 0"],["FeCl₃ + NaOH","rises slightly","exothermic","red-brown Fe(OH)₃ precipitate = evidence of reaction"],["Ice melting / water boiling","flat plateaus","endothermic","ΔS > 0"]],cap:"Typical results."}],
 worked:[["Syringe: 760 torr at 14 mL. Pressure at 24 mL?","P₂ = 760 × 14 / 24 = <b>443 torr</b>"],["Why enter 4 mL when the syringe reads 0 mL?","The connector hose holds 4 mL of gas, so every reading is syringe mark + 4 mL."]],
 proc:["Part A: one spoon of salt in a dry 30 mL beaker, add 10 mL DI water with the thermistor, record initial and max/min T.","Part B: 1 mL 1 M FeCl₃ + 1 mL 1 M NaOH in a test tube; record ΔT and appearance.","Part C: ice + water to 60 mL, stir, heat (100 → 200 → 400), log every 30 s through melting and boiling, sketch the curve.","Part D: syringe on pressure sensor; 60 mL syringe at 0/10/20/30/40 marks (enter 4/14/24/34/44 mL); 20 mL syringe at 0/5/10/15/20 (enter 4/9/14/19/24). Graph V (x) vs P (y) in Excel."],
 traps:["Never compress the syringe after it's attached: it breaks the pressure sensor.","The sign of ΔT is the water's; the reaction's ΔH has the opposite sign."],
 safety:["NaOH is about as alkaline as oven cleaner; flush 15 min. Hot plate stays hot. Syringes can pinch.","Waste: Part B mixture → waste container; Parts A and C down the sink."]},

{n:8, t:"Equilibrium & Le Châtelier", s:"FeSCN²⁺, cobalt complex, bromothymol blue",
 purpose:"Apply stresses to systems at equilibrium and watch which way they shift.",
 big:["<b>Equilibrium</b>: forward rate = reverse rate; amounts stay constant but both reactions keep going.","<b>Le Châtelier</b>: a stressed system shifts to reduce the stress.","<b>Add</b> a species → shift <b>away</b> from it. <b>Remove</b> a species → shift <b>toward</b> it.","Ag⁺ is a \"remover\": it precipitates SCN⁻ (AgSCN) or Cl⁻ (AgCl).","Spectator ions (Na⁺, NO₃⁻) cause <b>no shift</b>.","<b>Temperature</b>: treat heat as a reactant (endo) or product (exo). Heating favors the endothermic direction.","Cobalt: heating turns it blue → blue side is higher energy → blue → pink as written is <b>exothermic</b>.","Complex ions (metal + ligands like H₂O, NH₃, Cl⁻) are intensely colored."],
 eq:["Fe³⁺ (pale) + SCN⁻ ⇌ FeSCN²⁺ (red)","CoCl₄²⁻ (blue) + 6H₂O ⇌ Co(H₂O)₆²⁺ (pink) + 4Cl⁻","HBB (yellow, 470 nm) + H₂O ⇌ BB⁻ (blue, 635 nm) + H₃O⁺","K = [BB⁻][H₃O⁺] / [HBB] (liquid water left out)","K = [products]^coef / [reactants]^coef"],
 tables:[{h:["System","Stress","Shift","You see"],r:[["Fe/SCN","add Fe(NO₃)₃","right","deeper red"],["Fe/SCN","add NaSCN","right","deeper red"],["Fe/SCN","add AgNO₃ (removes SCN⁻)","left","red fades, white AgSCN"],["Fe/SCN","add NaNO₃","none","no change (spectators)"],["Cobalt","add 12 M HCl (Cl⁻)","left","blue"],["Cobalt","add water","right","pink"],["Cobalt","add AgNO₃ (removes Cl⁻)","right","pink + white AgCl"],["Cobalt","heat / cool","left / right","blue / pink"],["BTB","raise pH (less H₃O⁺)","right","bluer; A₆₃₅ ↑, A₄₇₀ ↓"]],cap:""}],
 proc:["Part A: 5 wells of 2 drops NaSCN + 2 drops 0.01 M Fe(NO₃)₃ + 3 drops water; well 1 = reference; add stresses to wells 2–5.","Part B (hood): 1 drop Co(NO₃)₂; 12 M HCl dropwise until blue, then water (pink) or AgNO₃. Heating shown by video.","Part C: blank, then each buffer (pH 6.30, 6.80, 7.30) + <b>6 drops</b> BTB; read A at ~635 and ~470 nm."],
 traps:["Only 6 drops of BTB: absorbance above 1.2 isn't accurate.","Adding a pure liquid (water) matters here only because water is written in the cobalt equation; it's still left out of K."],
 safety:["12 M HCl: hood only, vapors irritate; gloves encouraged. AgNO₃ stains skin (harmless).","Waste: Parts A and B → waste container; Part C down the drain."]},

{n:9, t:"Titration", s:"Acetic acid in vinegar with NaOH",
 purpose:"Find the concentration (molarity and mass %) of acetic acid in vinegar.",
 big:["<b>Titrant</b> = known concentration, in the buret (NaOH ~0.5 M). <b>Analyte</b> = unknown (acetic acid).","<b>Equivalence point</b>: mol base = mol acid (1:1). <b>Endpoint</b>: indicator changes color; very close to, not exactly, equivalence.","Phenolphthalein: colorless below ~pH 8, pink above. Endpoint = <b>faint pink lasting 30 s</b>. Dark purple-pink = overshot, redo.","On the pH curve the equivalence point is the <b>steepest</b> (near-vertical) part. Weak acid: starts ~pH 2.5–3, equivalence is <b>above 7</b> (acetate is basic).","M = mol/L = <b>mmol/mL</b>.","Adding ~40 mL DI water to the beaker doesn't change mol of acid → doesn't change the result.","Replicates should agree within <b>0.50 mL</b>.","Condition the buret with NaOH, remove tip bubbles, read to 0.01 mL, start at 0.00 mL."],
 eq:["HC₂H₃O₂ + OH⁻ → C₂H₃O₂⁻ + H₂O (1:1)","mmol NaOH = M × V(mL)","mmol acid = mmol NaOH","M acid = mmol acid ÷ mL vinegar","g acid = mol × 60.05 g/mol","mass % = g acid ÷ g vinegar × 100"],
 worked:[["Manual example: 10.2 mL of 0.100 M NaOH neutralizes 8.05 mL of acid.","10.2 × 0.100 = 1.02 mmol → 1.02 / 8.05 = <b>0.127 M</b>"],["7.00 mL vinegar (7.052 g) needs 11.62 mL of 0.5012 M NaOH.","0.5012 × 11.62 = 5.824 mmol → M = 5.824 / 7.00 = <b>0.8320 M</b> → 0.005824 mol × 60.05 = 0.3497 g → 0.3497 / 7.052 × 100 = <b>4.959%</b>"]],
 proc:["Calibrate pH probe with pH 4, 7, 10 buffers.","Condition 10 mL cylinder with vinegar; weigh empty 250 mL beaker, add 7.0 mL vinegar, weigh again (mass of vinegar).","Add ~40 mL DI water + 3 drops phenolphthalein, stir bar, probe ~½ inch deep.","Add NaOH: 2 mL steps to ~8 mL, 1 mL steps to ~11, ≤0.5 mL near the endpoint (pH jumps >0.3); rinse walls; dropwise. Continue ~5 mL past equivalence.","Part C: repeat with indicator only."],
 traps:["Air bubble in the buret tip that escapes during titration → volume reads too high → acid concentration too high.","Not conditioning the buret dilutes NaOH → more volume needed → acid too high.","Use mL of vinegar for molarity but grams of vinegar for mass %."],
 safety:["NaOH corrosive: flush eyes 15 min. pH probe bulb is fragile.","Waste: everything down the sink with water."]},

{n:10, t:"Acid-Base Studies", s:"pH of strong vs. weak acids/bases, dilution, neutralization",
 purpose:"Measure pH of strong/weak acids and bases, household chemicals, and an HCl + NaOH mixture.",
 big:["<b>Brønsted acid</b> = H⁺ donor; <b>base</b> = H⁺ acceptor. Conjugate pairs differ by one H⁺ (HF/F⁻, HCN/CN⁻).","Acidic: [H₃O⁺] > [OH⁻], pH < 7. Neutral pH 7 (298 K). Basic: pH > 7.","Strong acid: pH = −log(concentration). 0.010 M HCl → pH 2. A weak acid at the same concentration has a <b>higher</b> pH (0.010 M acetic acid ≈ 3.4).","Strong base: 0.010 M NaOH → pH 12. Weak base NH₃ at 0.010 M ≈ 10.6.","<b>Dilution</b>: each 10× dilution of a strong acid/base moves pH <b>one unit toward 7</b> (never past it).","Larger Kₐ = stronger acid.","<b>Indicator</b> = a weak acid whose conjugate base is a different color.","Part D: 10.0 mL of 0.010 M HCl = 1.0 × 10⁻⁴ mol. Equivalence at 10.0 mL of 0.010 M NaOH. 3 and 6 mL → still acidic; 12 mL → basic."],
 eq:["Kₐ = [A⁻][H₃O⁺]/[HA]","K_b = [HA][OH⁻]/[A⁻]","K_w = [H₃O⁺][OH⁻] = 1.0 × 10⁻¹⁴","pH = −log[H₃O⁺]; [H₃O⁺] = 10⁻ᵖᴴ","pOH = −log[OH⁻]; pH + pOH = 14"],
 tables:[{h:["Solution","Expected pH","Classification"],r:[["0.010 M HCl","2.0","strong acid"],["0.0010 M HCl","3.0","strong acid"],["0.00010 M HCl","4.0","strong acid"],["0.010 M HC₂H₃O₂","~3.4","weak acid"],["0.010 M NaOH","12.0","strong base"],["0.0010 M NaOH","11.0","strong base"],["0.010 M NH₃","~10.6","weak base"]],cap:"Calculated values; your probe readings will be close."},
         {h:["NaOH added","Mixture","pH (calc.)"],r:[["0.0 mL","acidic","2.00"],["3.0 mL","acidic","2.27"],["6.0 mL","acidic","2.60"],["12.0 mL","basic","10.96"]],cap:"Part D, 10.0 mL of 0.010 M HCl + 0.010 M NaOH."},
         {h:["Acidic","Basic","~Neutral"],r:[["vinegar, lemon juice, vitamin C, carbonated water","bleach, ammonia, baking soda, dishwasher detergent","baking powder is near neutral to slightly acidic (it contains both an acid and bicarbonate)"]],cap:"Part C household items (pH paper)."}],
 worked:[["pH 2.2 → [H₃O⁺]?","10⁻²·² = <b>6.3 × 10⁻³ M</b> (manual rounds to 0.006 M)"],["Part D at 12.0 mL NaOH","excess OH⁻ = 1.2×10⁻⁴ − 1.0×10⁻⁴ = 2.0×10⁻⁵ mol in 22.0 mL → 9.1×10⁻⁴ M → pOH 3.04 → <b>pH 10.96</b>"]],
 proc:["Calibrate probe (4, 7, 10). Measure seven solutions, rinsing between each; store probe in pH 7 buffer.","Household chemicals: 1–2 drops on pH paper; bleach bleaches paper (read immediately); ammonia last (vapors).","Part D: 10.0 mL 0.010 M HCl, add NaOH 3.0, 3.0, 6.0 mL, read pH each time."],
 traps:["Never mix solutions stronger than 0.1 M directly: neutralization can boil and splash.","Diluting an acid can't make it basic: pH approaches 7 from below."],
 safety:["HCl, NaOH, acetic acid, NH₃ are corrosive; vapors irritate.","Waste: all down the sink with lots of water."]},

{n:11, t:"Redox Reactions", s:"Oxidizing/reducing strength, galvanic cells, E°",
 purpose:"Rank oxidizing and reducing agents by reaction tests, then measure half-cell potentials.",
 big:["<b>OIL RIG</b>: Oxidation Is Loss (oxidation state ↑), Reduction Is Gain (oxidation state ↓).","<b>Reducing agent</b> loses e⁻ and is oxidized. <b>Oxidizing agent</b> gains e⁻ and is reduced.","Balance redox so e⁻ lost = e⁻ gained (2Ag⁺ + Cu → 2Ag + Cu²⁺).","Visible change (solid, gas, color) = reaction. Any agent that reacts with a test reagent is stronger than one that doesn't.","<b>Anode</b> = oxidation, <b>cathode</b> = reduction. <b>Salt bridge</b> (KNO₃) lets ions flow to keep each half-cell neutral.","E_cell = E_cathode − E_anode. SHE = 0 V reference.","Most negative reduction potential = strongest <b>reducing</b> agent (metal). Most positive = strongest <b>oxidizing</b> agent (ion).","Measured vs. Cu²⁺/Cu → add <b>+0.34 V</b> to convert to the SHE scale."],
 eq:["Zn + Cu²⁺ → Zn²⁺ + Cu","Zn → Zn²⁺ + 2e⁻ (oxidation)","Cu²⁺ + 2e⁻ → Cu (reduction)","MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O","Mg + 2H₂O → Mg(OH)₂ + H₂ (pink with phenolphthalein)","Zn + 2H⁺ → Zn²⁺ + H₂","E_SHE = E_vs Cu + 0.34 V","E_cell = E_cathode − E_anode"],
 tables:[{h:["Couple","vs. Cu²⁺/Cu","vs. SHE (E°)"],r:[["Zn²⁺/Zn","−1.10 V","−0.76 V"],["Pb²⁺/Pb","−0.47 V","−0.13 V"],["Cu²⁺/Cu","0.00 V","+0.34 V"],["Ag⁺/Ag","+0.46 V","+0.80 V"],["Mg²⁺/Mg (Part A only)","—","−2.37 V (goes at the very bottom)"]],cap:"Standard values; your measured potentials will be near these."},
         {h:["Test","Expected","Ranking"],r:[["Mg, Zn, Cu in water + phenolphthalein","only Mg reacts (pink, H₂)","reducers: Mg > Zn > Cu"],["Zn, Cu in 3 M HCl","Zn bubbles H₂; Cu nothing",""],["Cu²⁺, Mg²⁺, MnO₄⁻ with H₂O₂","MnO₄⁻ reacts (purple fades, bubbles)","oxidizers: MnO₄⁻ > Cu²⁺ > Mg²⁺"],["Cu²⁺, Mg²⁺ with KI","Cu²⁺ reacts (brown I₂ / CuI); Mg²⁺ nothing",""]],cap:"Typical results."}],
 worked:[["Zn/Cu galvanic cell E_cell?","Cu is the cathode (more positive): 0.34 − (−0.76) = <b>+1.10 V</b>"],["Zn measured −1.10 V vs. Cu. SHE value?","−1.10 + 0.34 = <b>−0.76 V</b>"],["Will Cu + Mg²⁺ react? Cu²⁺ + Mg?","Cu can't reduce Mg²⁺ (Cu is the weaker reducer): <b>no</b>. Mg reduces Cu²⁺: <b>yes</b>."]],
 proc:["A1: 3 drops Cu(NO₃)₂, Mg(NO₃)₂, acidic KMnO₄; add 2 drops 3% H₂O₂ (R/NR); non-reactors get 3 drops 0.1 M KI.","A2: Cu, Mg, Zn in tap water + phenolphthalein; non-reactors then get 10 mL 3 M HCl (hood).","B: Multi-EChem cell, KNO₃ salt bridge in the center; black clip on Cu (well 1); red clip on Cu (≈0 V), then Ag (positive), Zn, Pb."],
 traps:["Positive reading with Ag means Cu²⁺/Cu is the anode; negative (Zn, Pb) means Cu²⁺/Cu is the cathode.","Reducing agents are oxidized; don't swap the labels."],
 safety:["KMnO₄ = strong oxidizer, corrosive; 3 M HCl in the hood. Pb(NO₃)₂ toxic. Metals make H₂ gas: keep away from flames.","Waste: A1 and B solutions into the waste container; used metals into the Used Metal Jar (loosely capped, H₂); wires go back; other liquids down the sink."]}
];

// Quiz bank: l = lab, a = correct option index
const QUIZ = [
// Lab 0
{l:0,q:"A chemical splashes in your eye. How long do you flush at the eyewash?",o:["2 minutes","5 minutes","At least 15 minutes","Until it stops stinging"],a:2,e:"The manual says at least 15 minutes, holding the eyes open, and have someone tell the TA."},
{l:0,q:"A buret is read to the nearest:",o:["1 mL","0.1 mL","0.01 mL","0.001 mL"],a:2,e:"Buret marks are 0.1 mL apart; you estimate one more digit, 0.01 mL."},
{l:0,q:"A procedure says \"measure 5.00 mL.\" Which glassware?",o:["Beaker","Graduated cylinder","Volumetric pipet or buret","Erlenmeyer flask"],a:2,e:"Two decimal places means precise glassware. \"About 5 mL\" would be a graduated cylinder."},
{l:0,q:"Why do you condition a buret with the titrant?",o:["To dry it","So leftover water doesn't dilute the titrant","To calibrate the scale","To remove grease"],a:1,e:"A buret can't be dried, so you rinse it with small portions of the solution to replace the water."},
{l:0,q:"How many significant figures in 0.00890?",o:["2","3","5","6"],a:1,e:"Leading zeros don't count; the trailing zero after the decimal does: 8, 9, 0."},
{l:0,q:"2.023 + 4.71 = ?",o:["6.733","6.73","6.7","7"],a:1,e:"Addition keeps the fewest decimal places (2, from 4.71)."},
{l:0,q:"A balance that always reads 0.050 g too high causes:",o:["Random error, hurts precision","Systematic error, hurts accuracy","No error if you average","Proportional error only"],a:1,e:"An error that pushes every reading the same way is systematic (determinate): results can be precise but inaccurate."},
{l:0,q:"The hottest part of a Bunsen burner flame is:",o:["The yellow outer tip","The tip of the inner blue cone","Right at the barrel","The base of the flame"],a:1,e:"Adjust for two distinct blue regions; the tip of the inner dark-blue cone is hottest."},
{l:0,q:"How should you finish delivering from a volumetric (TD) pipet?",o:["Blow out the last drop","Let it drain and touch off the tip","Shake it","Rinse it into the flask"],a:1,e:"TD pipets are calibrated to leave a small residue. Blowing it out delivers too much."},
{l:0,q:"You arrive more than 10 minutes late to lab. Result?",o:["−5 points","Unexcused absence and 0/50 InLab","You can make it up","Nothing if the PreLab is done"],a:1,e:"Over 10 min late counts as an unexcused absence, which zeroes the InLab."},
{l:0,q:"How many of the 11 labs must you attend to avoid failing?",o:["7","8","9","11"],a:2,e:"9 of 11. There's no Incomplete in CH 102."},
{l:0,q:"Loading a centrifuge with one sample tube, you should:",o:["Run it alone","Put a tube of water with the same volume directly opposite","Put a tube anywhere","Fill the tube to the top"],a:1,e:"Balance the rotor with an equal-volume tube opposite yours."},
{l:0,q:"Which may go down the drain?",o:["Ag⁺ and Pb²⁺ solutions","Organic solvents","Dilute non-toxic acids and bases with lots of water","Any solution in small amounts"],a:2,e:"Never heavy metals or organic solvents. Dilute acids/bases may go down with plenty of water when the manual allows."},
{l:0,q:"You come to lab in leggings. What happens?",o:["Nothing","You have 10 minutes to change, or you observe only and lose 15 InLab points","You're dropped from the course","You wear a lab coat over them"],a:1,e:"Dress code: 10 minutes to fix it, otherwise observe from a distance and lose 15 points."},
// Lab 1
{l:1,q:"Density of pure water at 25 °C?",o:["0.997 kg/mL","1.00 g/mL","18.0 g/mL","1.00 g/L"],a:1,e:"The manual says to memorize it: 1 g of water occupies 1 mL."},
{l:1,q:"5.00 g of H₂O is how many moles?",o:["0.278 mol","90.0 mol","3.60 mol","0.0278 mol"],a:0,e:"5.00 g × (1 mol/18.0 g) = 0.278 mol."},
{l:1,q:"The volume of a single water molecule is about:",o:["18.0 mL","1.00 mL","2.99 × 10⁻²³ mL","6.02 × 10²³ mL"],a:2,e:"Molar volume 18.0 mL/mol ÷ 6.02 × 10²³ molecules/mol."},
{l:1,q:"12 marbles raise the water level from 50.0 mL to 62.4 mL. Volume of one marble?",o:["12.4 mL","1.03 mL","5.20 mL","0.97 mL"],a:1,e:"Displaced 12.4 mL ÷ 12 = 1.03 mL."},
{l:1,q:"A dozen kernels weigh 1.524 g. Molar mass of popcorn?",o:["0.127 g/mol","1.524 g/mol","7.65 × 10²² g/mol","9.18 × 10²³ g/mol"],a:2,e:"One kernel = 0.1270 g; × 6.022 × 10²³ = 7.65 × 10²² g/mol."},
{l:1,q:"Why tilt the cylinder and roll marbles in?",o:["To speed it up","To avoid splashing water out, which would make the displaced volume too small","To warm the water","To dry the marbles"],a:1,e:"Lost water lowers the final reading."},
{l:1,q:"Your water filled the cylinder to 17.8 mL instead of 18 mL. What do you record?",o:["18 mL","18.0 mL","17.8 mL","Redo until exactly 18.0"],a:2,e:"Recording the exact volume matters more than hitting the target."},
// Lab 2
{l:2,q:"A solution absorbs mostly violet-blue light (~430 nm). It looks:",o:["violet","blue","yellow","colorless"],a:2,e:"You see the complement of the absorbed color. Tartrazine absorbs ~430 nm and looks yellow."},
{l:2,q:"In a flame test, the color you see is:",o:["The complement of the absorbed color","The light emitted as electrons fall to lower levels","Reflected light","The color of the HCl"],a:1,e:"Emission gives the color directly; complements only apply to absorption."},
{l:2,q:"T = 0.25. What is A?",o:["0.25","0.60","1.39","−0.60"],a:1,e:"A = −log(0.25) = 0.602."},
{l:2,q:"Which has the highest photon energy?",o:["700 nm red","580 nm yellow","520 nm green","410 nm violet"],a:3,e:"E = hc/λ: shortest wavelength, highest energy."},
{l:2,q:"Why is a water blank read first?",o:["To measure I₀ (calibrate the instrument)","To clean the cuvette","To heat the lamp","To measure the dye's λmax"],a:0,e:"The blank sets the 100% transmittance reference."},
{l:2,q:"How do you clean the nichrome loop?",o:["Wipe with a paper towel","Dip in 3 M HCl and heat in the flame until no color","Rinse with tap water","Dip in NaOH"],a:1,e:"Repeat until the flame shows no color (a pale yellow can remain)."},
{l:2,q:"Green food coloring's absorption spectrum shows:",o:["One peak at 520 nm","Two groups of peaks (yellow dye + blue dye)","No peaks","A peak only in the UV"],a:1,e:"It's a mix: one dye absorbs blue-violet, the other absorbs orange-red, so green is transmitted."},
{l:2,q:"Energy of a 470 nm photon?",o:["4.23 × 10⁻¹⁹ J","4.23 × 10⁻²⁸ J","2.36 × 10¹⁸ J","6.38 × 10¹⁴ J"],a:0,e:"(6.626 × 10⁻³⁴)(3.0 × 10⁸)/(470 × 10⁻⁹) = 4.23 × 10⁻¹⁹ J. 6.38 × 10¹⁴ is the frequency in Hz."},
{l:2,q:"Waste from the flame tests goes:",o:["Into the heavy-metal waste","Down the sink with plenty of water","Back in the bottles","In the trash"],a:1,e:"Flame-test solutions and the HCl go down the sink; dye vials are returned unopened."},
// Lab 3
{l:3,q:"Why were all cations supplied as nitrate salts?",o:["Nitrates are cheap","All nitrates are soluble, so a precipitate must come from the other ions","Nitrate is colored","Nitrate reacts with every anion"],a:1,e:"Nitrate is a spectator that never precipitates."},
{l:3,q:"Net ionic equation for Pb(NO₃)₂(aq) + 2KI(aq)?",o:["Pb²⁺ + 2I⁻ → PbI₂(s)","K⁺ + NO₃⁻ → KNO₃(s)","Pb(NO₃)₂ → Pb²⁺ + 2NO₃⁻","2K⁺ + 2I⁻ → 2KI(s)"],a:0,e:"K⁺ and NO₃⁻ are spectators."},
{l:3,q:"Correct formula for the precipitate from Al³⁺ and PO₄³⁻:",o:["Al₃PO₄","AlPO₄","Al(PO₄)₃","Al₃(PO₄)₂"],a:1,e:"+3 and −3 balance 1:1."},
{l:3,q:"Which pair breaks the \"±1 ions are soluble\" rule?",o:["Na⁺ + Cl⁻","K⁺ + OH⁻","Ag⁺ + Cl⁻","NH₄⁺ + NO₃⁻"],a:2,e:"AgCl precipitates even though both ions are ±1."},
{l:3,q:"Na₃PO₄ is soluble even though most phosphates aren't. This shows:",o:["The phosphate rule wins","The Group 1 rule takes precedence","Na₃PO₄ is a weak acid","Phosphate is a spectator"],a:1,e:"Group 1 and NH₄⁺ compounds are soluble, which overrides the phosphate rule."},
{l:3,q:"By Coulomb's law, which pair attracts most strongly in water (same distance)?",o:["Na⁺ / Cl⁻","Mg²⁺ / Cl⁻","Al³⁺ / PO₄³⁻","K⁺ / NO₃⁻"],a:2,e:"F ∝ q₁q₂: 3 × 3 is largest, which is why highly charged pairs precipitate."},
{l:3,q:"Net ionic for Mg(NO₃)₂ + Na₂CO₃?",o:["Mg²⁺ + CO₃²⁻ → MgCO₃(s)","Na⁺ + NO₃⁻ → NaNO₃(s)","Mg²⁺ + 2Na⁺ → MgNa₂","No reaction"],a:0,e:"Magnesium carbonate precipitates; Na⁺ and NO₃⁻ are spectators."},
{l:3,q:"Which perchlorate (ClO₄⁻) combination precipitates?",o:["Pb(ClO₄)₂","AgClO₄","Fe(ClO₄)₃","None of them"],a:3,e:"Perchlorate is −1 and behaves like nitrate: all soluble."},
{l:3,q:"Which pair gives a yellow precipitate in Part B?",o:["Pb²⁺ + I⁻","K⁺ + I⁻","Na⁺ + NO₃⁻","Mg²⁺ + Cl⁻"],a:0,e:"PbI₂ is the classic bright-yellow solid. AgI is pale yellow too."},
{l:3,q:"Lab 3 waste goes:",o:["Down the sink","In the labeled waste container (heavy metals)","In the trash","Back in the bottles"],a:1,e:"Pb²⁺, Ag⁺ and others are toxic; rinse into the waste with minimal water."},
// Lab 4
{l:4,q:"The first reagent added to the Ag⁺/Fe³⁺/Ba²⁺ mixture is:",o:["NH₃","H₂SO₄","HCl","NaSCN"],a:2,e:"HCl precipitates only Ag⁺ as AgCl."},
{l:4,q:"7.5 M NH₃ is added to the supernatant. What precipitates?",o:["AgCl","Fe(OH)₃","BaSO₄","Nothing"],a:1,e:"NH₃ makes it basic; Fe³⁺ forms rust-brown Fe(OH)₃. Ba(OH)₂ is soluble, so Ba²⁺ stays."},
{l:4,q:"How is Ag⁺ confirmed?",o:["Red color with SCN⁻","Dissolve AgCl in NH₃, then HNO₃ brings white AgCl back","White precipitate with H₂SO₄","Flame test"],a:1,e:"NH₃ forms soluble Ag(NH₃)₂⁺; acidifying with HNO₃ re-forms AgCl."},
{l:4,q:"How is Fe³⁺ confirmed?",o:["Dissolve Fe(OH)₃ in HCl, add NaSCN → blood red","Add HNO₃ → white solid","Add H₂SO₄ → white solid","It turns blue in NH₃"],a:0,e:"FeSCN²⁺ is deep red."},
{l:4,q:"Why wash a precipitate with water before testing it?",o:["To dissolve it","To remove trapped soluble ions that could give a false positive","To cool it","To weigh it"],a:1,e:"Leftover ions from the supernatant can trigger the next confirmatory test."},
{l:4,q:"How do you test whether precipitation is complete?",o:["Weigh the solid","Add one more drop of reagent to the clear supernatant; no new cloudiness = complete","Shake harder","Heat it"],a:1,e:"Centrifuge first, then add a drop down the tube wall."},
{l:4,q:"Unknown: HCl → no solid; NH₃ → brown solid; H₂SO₄ → white solid. Ions present?",o:["Ag⁺ only","Fe³⁺ and Ba²⁺","Ag⁺ and Ba²⁺","All three"],a:1,e:"No AgCl means no Ag⁺. Brown Fe(OH)₃ and white BaSO₄ confirm the others."},
{l:4,q:"The liquid above a centrifuged solid is the:",o:["Precipitate","Supernatant","Filtrate cake","Decant"],a:1,e:"You decant (pour off) the supernatant."},
{l:4,q:"Where does Lab 4 waste go?",o:["Down the sink if dilute","All of it into the waste container; nothing down the sink","Trash","Fume hood drain"],a:1,e:"All solutions and solids contain heavy-metal cations."},
// Lab 5
{l:5,q:"Shared pairs (SP) for CO₂?",o:["2","3","4","8"],a:2,e:"ER = 3 × 8 = 24, VE = 4 + 12 = 16, SP = ½(24 − 16) = 4 (two double bonds)."},
{l:5,q:"For formate, CHO₂⁻, VE = ?",o:["17","18","26","16"],a:1,e:"C 4 + H 1 + O 12 + 1 for the − charge = 18."},
{l:5,q:"Molecular shape of NH₃?",o:["Trigonal planar","Tetrahedral","Trigonal pyramidal","Bent"],a:2,e:"4 electron groups (1 lone pair): tetrahedral electron geometry, pyramidal shape, ~107°."},
{l:5,q:"Bond angle in H₂O?",o:["180°","120°","109.5°","~104.5°"],a:3,e:"Two lone pairs squeeze the angle below 109.5°."},
{l:5,q:"How many electron groups does a C=O double bond count as in VSEPR?",o:["1","2","4","0"],a:0,e:"Double and triple bonds each count as one group."},
{l:5,q:"Rank C–C bond lengths:",o:["ethane < ethene < ethyne","ethyne < ethene < ethane","all equal","ethene < ethane < ethyne"],a:1,e:"Higher bond order is shorter: triple (0.120 nm) < double (0.134) < single (0.154)."},
{l:5,q:"How can you confirm benzene's resonance structures are equal?",o:["All six C–C bond lengths are the same","It has 6 carbons","It's planar","It has no lone pairs"],a:0,e:"Equal resonance forms give identical bond lengths (~0.139 nm)."},
{l:5,q:"Formal charge on N in NH₄⁺?",o:["0","+1","−1","+4"],a:1,e:"FC = 5 − 4 bonds − 0 = +1."},
{l:5,q:"By formal-charge rules, the best SCN⁻ structure puts the −1 on:",o:["S","C","N","spread on all"],a:2,e:"[S=C=N]⁻ puts the negative charge on N, the more electronegative atom."},
{l:5,q:"SO₂ has 3 electron groups on S (one lone pair). Shape and hybridization?",o:["Linear, sp","Bent, sp²","Bent, sp³","Trigonal planar, sp²"],a:1,e:"Trigonal planar electron geometry, bent molecular shape (~119°), sp²."},
{l:5,q:"CH₂O (formaldehyde) has what shape?",o:["Trigonal pyramidal","Trigonal planar","Tetrahedral","Bent"],a:1,e:"C has 3 groups (2 C–H, 1 C=O) and no lone pairs: 120°, sp²."},
// Lab 6
{l:6,q:"Atoms in one face-centered cubic unit cell?",o:["1","2","4","14"],a:2,e:"8 corners × 1/8 + 6 faces × 1/2 = 4."},
{l:6,q:"Coordination number in body-centered cubic?",o:["4","6","8","12"],a:2,e:"The center atom touches all 8 corners."},
{l:6,q:"Rank packing efficiency:",o:["SC > BCC > FCC","FCC > BCC > SC","BCC > FCC > SC","all equal"],a:1,e:"74% > 68% > 52%."},
{l:6,q:"An atom on a cube edge contributes how much to the cell?",o:["1/8","1/4","1/2","1"],a:1,e:"Four cells share an edge."},
{l:6,q:"How many Na⁺ and Cl⁻ are in one NaCl unit cell?",o:["1 and 1","2 and 2","4 and 4","8 and 6"],a:2,e:"Both form FCC arrangements: 4 each, matching NaCl 1:1."},
{l:6,q:"Why isn't CsCl called body-centered cubic?",o:["It has no center atom","The center ion is a different ion from the corner ions","It has 2 Cs per cell","It's amorphous"],a:1,e:"A BCC lattice needs identical particles. CsCl is two interpenetrating simple cubic lattices; CN = 8."},
{l:6,q:"In fluorite (CaF₂), the F⁻ ions per unit cell:",o:["4","8","2","1"],a:1,e:"Ca²⁺ FCC = 4; 8 F⁻ inside; 4:8 = 1:2 = CaF₂."},
{l:6,q:"Model FCC cell edge = 4.2 cm. Atom density?",o:["0.95 spheres/cm³","0.054 spheres/cm³","0.24 spheres/cm³","17.6 spheres/cm³"],a:1,e:"4 ÷ (4.2)³ = 4 ÷ 74.1 = 0.054."},
{l:6,q:"Coordination number of Na⁺ in NaCl?",o:["4","6","8","12"],a:1,e:"Each Na⁺ touches 6 Cl⁻ (and vice versa)."},
// Lab 7
{l:7,q:"Dissolving NH₄NO₃ drops the water from 22.5 °C to 17.3 °C. The process is:",o:["Exothermic, ΔH < 0","Endothermic, ΔH > 0","Neither","Exothermic, ΔH > 0"],a:1,e:"ΔT = −5.2 °C: the water lost heat to the dissolving salt."},
{l:7,q:"Which salt would work in a cold pack?",o:["CaCl₂","NH₄NO₃","Both","Neither"],a:1,e:"NH₄NO₃ dissolving is endothermic; CaCl₂ warms the water."},
{l:7,q:"NH₄NO₃ dissolving is endothermic yet spontaneous. So ΔS must be:",o:["Negative","Zero","Positive","Can't be spontaneous"],a:2,e:"ΔG = ΔH − TΔS < 0 with ΔH > 0 requires a positive TΔS."},
{l:7,q:"Exothermic with ΔS > 0 is spontaneous:",o:["Never","Only at high T","Only at low T","Always"],a:3,e:"Both terms make ΔG negative."},
{l:7,q:"On the ice-water heating curve, the flat regions mean:",o:["The heater is off","Heat is going into a phase change, so T stays constant","The thermistor failed","The water is cooling"],a:1,e:"Melting at 0 °C and boiling near 100 °C."},
{l:7,q:"760 torr at 14 mL; volume increased to 44 mL at constant T. Pressure?",o:["2390 torr","242 torr","760 torr","1340 torr"],a:1,e:"Boyle: 760 × 14 / 44 = 242 torr."},
{l:7,q:"Why do you add 4 mL to every syringe reading?",o:["Calibration fudge","The connector hose holds 4 mL of gas","The syringe is mislabeled","To convert to liters"],a:1,e:"The \"0 mL\" mark actually has 4 mL of gas in the system."},
{l:7,q:"In Part D, the independent variable is:",o:["Pressure","Volume","Temperature","Moles"],a:1,e:"You set the volume (x-axis) and measure the pressure (y-axis)."},
{l:7,q:"Evidence that FeCl₃ and NaOH reacted:",o:["Nothing changes","A red-brown solid (Fe(OH)₃) forms and the temperature changes","It turns blue","It boils"],a:1,e:"A new solid and a temperature change are signs of a chemical reaction."},
{l:7,q:"Entropy change when water boils:",o:["Decreases greatly","Stays the same","Increases slightly","Increases greatly"],a:3,e:"Liquid → gas is the largest entropy jump."},
// Lab 8
{l:8,q:"Adding Fe(NO₃)₃ to the red Fe³⁺/SCN⁻/FeSCN²⁺ mixture:",o:["Shifts left, fades","Shifts right, deeper red","No change","Turns blue"],a:1,e:"Adding a reactant pushes the system toward products."},
{l:8,q:"AgNO₃ is added to the FeSCN²⁺ well. What happens?",o:["Deeper red","Ag⁺ removes SCN⁻ as AgSCN(s), shift left, red fades","No change","Shift right"],a:1,e:"Removing a reactant shifts the equilibrium toward reactants."},
{l:8,q:"Adding NaNO₃ to the Fe/SCN system:",o:["Shifts right","Shifts left","No shift: Na⁺ and NO₃⁻ are spectators","Forms a precipitate"],a:2,e:"Neither ion appears in the equilibrium."},
{l:8,q:"Adding 12 M HCl to pink Co(H₂O)₆²⁺ turns it blue because:",o:["Cl⁻ is a product, so the system shifts left to CoCl₄²⁻","HCl is a catalyst","It heats the solution","H⁺ is a reactant"],a:0,e:"CoCl₄²⁻ + 6H₂O ⇌ Co(H₂O)₆²⁺ + 4Cl⁻; extra Cl⁻ drives it left."},
{l:8,q:"Heating the cobalt solution turns it blue. The reaction CoCl₄²⁻ → Co(H₂O)₆²⁺ (blue → pink) is:",o:["Endothermic","Exothermic","Neither","Can't tell"],a:1,e:"Heat favors the blue (higher-energy) side, so going blue → pink releases heat."},
{l:8,q:"Raising the buffer pH (lowering [H₃O⁺]) for bromothymol blue:",o:["Shifts left, more yellow HBB","Shifts right, more blue BB⁻; A at 635 nm rises","No change","A at 470 nm rises"],a:1,e:"Removing a product (H₃O⁺) shifts right."},
{l:8,q:"Equilibrium expression for HBB + H₂O ⇌ BB⁻ + H₃O⁺:",o:["[HBB]/[BB⁻][H₃O⁺]","[BB⁻][H₃O⁺]/[HBB]","[BB⁻][H₃O⁺]/[HBB][H₂O]","[BB⁻]/[HBB]"],a:1,e:"Liquid water is left out of K."},
{l:8,q:"At equilibrium:",o:["Both reactions stop","Forward and reverse rates are equal","[reactants] = [products]","Only products remain"],a:1,e:"It's dynamic: species keep interconverting, but amounts stay constant."},
{l:8,q:"Why only 6 drops of bromothymol blue?",o:["It's expensive","Absorbance above ~1.2 isn't accurate","More would change the pH","It's toxic"],a:1,e:"The manual warns that absorbance above 1.2000 is inaccurate."},
{l:8,q:"Adding AgNO₃ to the blue cobalt/HCl well turns it pink because:",o:["Ag⁺ removes Cl⁻ as AgCl, shift right","Ag⁺ is pink","NO₃⁻ is a reactant","It cools the solution"],a:0,e:"Removing a product shifts toward products."},
// Lab 9
{l:9,q:"The difference between endpoint and equivalence point:",o:["They're identical by definition","Equivalence = mol base equals mol acid; endpoint = indicator changes color (very close)","Endpoint comes first always","Equivalence is when it turns pink"],a:1,e:"A good indicator makes them nearly the same."},
{l:9,q:"11.62 mL of 0.5012 M NaOH neutralizes 7.00 mL of vinegar. Molarity of acetic acid?",o:["0.302 M","0.832 M","4.07 M","0.0832 M"],a:1,e:"0.5012 × 11.62 = 5.824 mmol ÷ 7.00 mL = 0.8320 M."},
{l:9,q:"Same titration: vinegar sample mass 7.052 g. Mass % acetic acid (60.05 g/mol)?",o:["4.96%","8.32%","0.350%","49.6%"],a:0,e:"0.005824 mol × 60.05 = 0.3497 g ÷ 7.052 g × 100 = 4.959%."},
{l:9,q:"Phenolphthalein is:",o:["Pink in acid, colorless in base","Colorless below ~pH 8, pink above","Yellow then blue","Always pink"],a:1,e:"Endpoint = faint pink lasting 30 s."},
{l:9,q:"The solution turns dark purple-pink. You:",o:["Record it as the endpoint","Overshot; repeat, adding the last ~1 mL dropwise","Add more vinegar and continue","Add acid"],a:1,e:"The endpoint is the first faint, lasting pink."},
{l:9,q:"For acetic acid titrated with NaOH, the pH at equivalence is:",o:["Exactly 7","Below 7","Above 7","14"],a:2,e:"The product acetate is a weak base."},
{l:9,q:"On the titration curve, the equivalence point is where:",o:["pH = 7","The curve is steepest (nearly vertical)","pH stops changing","The curve starts"],a:1,e:"The manual: find the buret volume where the slope is steepest."},
{l:9,q:"An air bubble in the buret tip escapes during the titration. Calculated acid concentration is:",o:["Too high","Too low","Unaffected","Zero"],a:0,e:"The buret reads more volume than was really delivered."},
{l:9,q:"Adding 40 mL of DI water to the vinegar before titrating:",o:["Lowers the calculated concentration","Has no effect on the result","Raises it","Ruins the titration"],a:1,e:"Moles of acid don't change; only its volume does."},
{l:9,q:"Replicate titrations in this lab should agree within:",o:["0.01 mL","0.50 mL","2 mL","5 mL"],a:1,e:"0.50 mL here (skilled technique can reach 0.10 mL)."},
// Lab 10
{l:10,q:"pH of 0.010 M HCl?",o:["0.010","1.0","2.0","12.0"],a:2,e:"Strong acid: pH = −log(0.010) = 2.0."},
{l:10,q:"0.010 M NaOH is diluted to 0.0010 M. pH goes:",o:["12 → 13","12 → 11","12 → 2","stays 12"],a:1,e:"Each 10× dilution moves pH one unit toward 7."},
{l:10,q:"0.010 M acetic acid reads pH ≈ 3.4, not 2. This shows it is:",o:["A strong acid","A weak acid (partly ionized)","A base","Contaminated"],a:1,e:"Only a small fraction donates H⁺."},
{l:10,q:"0.010 M NH₃ reads pH ≈ 10.6. It is:",o:["A strong base","A weak base","An acid","Neutral"],a:1,e:"A strong base at 0.010 M would read 12."},
{l:10,q:"pH = 2.2. [H₃O⁺] = ?",o:["2.2 M","6.3 × 10⁻³ M","1.6 × 10⁻¹² M","0.22 M"],a:1,e:"10⁻²·² = 6.3 × 10⁻³ M."},
{l:10,q:"Conjugate acid of CN⁻:",o:["HCN","CN²⁻","H₂CN⁺","C⁻"],a:0,e:"Add one H⁺."},
{l:10,q:"10.0 mL of 0.010 M HCl + 6.0 mL of 0.010 M NaOH. The mixture is:",o:["Acidic","Neutral","Basic","Can't tell"],a:0,e:"1.0 × 10⁻⁴ mol HCl vs 6.0 × 10⁻⁵ mol NaOH: acid left over (pH ≈ 2.6)."},
{l:10,q:"Same HCl + 12.0 mL NaOH. pH ≈ ?",o:["2.6","7.0","10.96","12.0"],a:2,e:"Excess 2.0 × 10⁻⁵ mol OH⁻ in 22.0 mL → 9.1 × 10⁻⁴ M → pOH 3.04 → pH 10.96."},
{l:10,q:"Which household item is basic?",o:["Lemon juice","Vinegar","Baking soda","Carbonated water"],a:2,e:"Bicarbonate is a weak base (pH ~8–9)."},
{l:10,q:"Why test ammonia last on the pH paper?",o:["It's the most expensive","Its vapors react with the other pH strips","It bleaches the paper","It's neutral"],a:1,e:"Bleach is the one that bleaches the paper (read it immediately)."},
{l:10,q:"An acid-base indicator is:",o:["A strong acid","A weak acid whose conjugate base is a different color","A buffer","A salt"],a:1,e:"Acid color in acid, base color in base."},
{l:10,q:"Kw at 298 K:",o:["1.0 × 10⁻⁷","1.0 × 10⁻¹⁴","14","7"],a:1,e:"[H₃O⁺][OH⁻] = 1.0 × 10⁻¹⁴, so pure water has 1.0 × 10⁻⁷ M of each."},
// Lab 11
{l:11,q:"In Zn + Cu²⁺ → Zn²⁺ + Cu, the reducing agent is:",o:["Zn","Cu²⁺","Zn²⁺","Cu"],a:0,e:"Zn loses electrons (is oxidized), so it's the reducing agent."},
{l:11,q:"Oxidation is:",o:["Gain of electrons","Loss of electrons; oxidation state increases","Gain of oxygen only","Loss of protons"],a:1,e:"OIL RIG."},
{l:11,q:"Only Mg reacts with water (pink with phenolphthalein); Zn reacts only with HCl; Cu reacts with neither. Reducing strength:",o:["Cu > Zn > Mg","Mg > Zn > Cu","Zn > Mg > Cu","All equal"],a:1,e:"A metal that reacts with a weaker oxidizer (water) is a stronger reducer."},
{l:11,q:"Why does phenolphthalein turn pink around Mg in water?",o:["Mg is pink","Mg + 2H₂O → Mg(OH)₂ + H₂ makes the solution basic","H₂ is pink","The water is acidic"],a:1,e:"OH⁻ is produced."},
{l:11,q:"Zn measures −1.10 V vs. Cu²⁺/Cu. Its potential vs. SHE?",o:["−1.44 V","−0.76 V","+0.76 V","−1.10 V"],a:1,e:"Add +0.34 V: −1.10 + 0.34 = −0.76 V."},
{l:11,q:"E_cell for Zn | Zn²⁺ || Cu²⁺ | Cu?",o:["−1.10 V","+0.42 V","+1.10 V","+0.34 V"],a:2,e:"E_cathode − E_anode = 0.34 − (−0.76)."},
{l:11,q:"The cathode is where:",o:["Oxidation occurs","Reduction occurs","The salt bridge is","Electrons are produced"],a:1,e:"Red cat: reduction at the cathode; oxidation at the anode."},
{l:11,q:"The KNO₃ salt bridge's job:",o:["Supply electrons","Let ions flow so each half-cell stays neutral","Measure voltage","Reduce Cu²⁺"],a:1,e:"Without it, charge builds up and current stops."},
{l:11,q:"Will Cu(s) react with Mg²⁺(aq)?",o:["Yes","No","Only when heated","Only in acid"],a:1,e:"Cu is a much weaker reducer than Mg; but Cu²⁺ + Mg does react."},
{l:11,q:"The strongest oxidizing agent has:",o:["The most negative reduction potential","The most positive reduction potential","Zero potential","Highest-energy filled orbitals"],a:1,e:"Lowest-energy vacant orbitals = most positive E°."},
{l:11,q:"Balanced: Ag⁺ + Cu → ?",o:["Ag + Cu²⁺","2Ag⁺ + Cu → 2Ag + Cu²⁺","Ag⁺ + Cu → Ag + Cu⁺","2Ag + Cu²⁺ → 2Ag⁺ + Cu"],a:1,e:"Cu gives 2 e⁻; each Ag⁺ takes 1."},
{l:11,q:"Why isn't the used-metal jar tightly capped?",o:["To let it dry","H₂ gas from the metals could build pressure","Metals need oxygen","No reason"],a:1,e:"Reducing metals keep making H₂ with leftover acid or water."},
{l:11,q:"Which oxidizer reacted with H₂O₂ (purple disappears)?",o:["Mg²⁺","Cu²⁺","MnO₄⁻","K⁺"],a:2,e:"Permanganate is the strongest oxidizer of the three."}
];

